// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.implimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.memory.EntityTypeimport com.roshan.persona.brain.memory.FactSourceimport com.roshan.persona.brain.memory.KgEntityimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryIdimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.memory.MemoryTypeimport com.roshan.persona.brain.memory.UserFactimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.memory.recall.ContextWindowManagerimport com.roshan.persona.memory.recall.HybridRecallEngineimport com.roshan.persona.memory.repository.EpisodicMemoryRepositoryimport com.roshan.persona.memory.repository.KnowledgeGraphRepositoryimport com.roshan.persona.memory.repository.UserFactRepositoryimport timber.log.Timberimport java.time.Instantimport com.roshan.persona.common.AppError/** * NOUS — Memory Interface Implementation. * * Implements [MemoryInterface] (defined in Brain Module 2) using * Room-backed repositories. This is the real implementation that * Brain's BrainOrchestrator uses — NOT a stub. * * Architecture: *   - recall → HybridRecallEngine (keyword + vector + KG fusion) *   - store → EpisodicMemoryRepository (async embedding) *   - getUserFacts → UserFactRepository *   - getActiveEntities → KnowledgeGraphRepository *   - forget → EpisodicMemoryRepository (soft-delete/tombstone) * * @see <a href="docs/strategy/module-3-strategy-v2.md">§12 Brain Integration</a> */class MemoryInterfaceImpl(    private val episodicRepo: EpisodicMemoryRepository,    private val userFactRepo: UserFactRepository,    private val kgRepo: KnowledgeGraphRepository,    private val recallEngine: HybridRecallEngine,    private val contextWindow: ContextWindowManager = ContextWindowManager(),    /**     * Optional embedder — when provided, embeddings are computed + stored     * on every `store()` call so vector search works.     *     * Wired by [com.roshan.persona.memory.di.MemoryModule] when Module 6's     * OmniSlmEmbedder is available. When null (early boot / tests), embeddings     * are NOT stored — vector search returns empty, keyword search still works.     */    private val embedder: MemoryEmbedder? = null,) : MemoryInterface {    /**     * Recall top-K relevant memories using hybrid search.     * Results are trimmed to fit LLM context window.     */    override suspend fun recall(query: String, k: Int): Result<List<Memory>> {        return try {            val memories = recallEngine.recall(query, k)            // Trim to context window            val trimmed = contextWindow.trimToFit(memories)            Result.Success(trimmed, CorrelationId.generate(), 0)        } catch (e: Exception) {            Timber.e(e, "Recall failed for query: $query")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Store a new episodic memory.     *     * After persisting to Room, kicks off async embedding computation via     * [embedder] (if wired). The embedding is stored in the HNSW index so     * vector search can find this memory later.     *     * **Previously**: `storeEmbedding()` was never called — vector search     * returned empty forever. Audit Task ID: audit-m3-memory P0.     */    override suspend fun store(memory: Memory): Result<MemoryId> {        val storeResult = episodicRepo.store(memory)        if (storeResult is Result.Success && embedder != null) {            try {                val embedding = embedder.embed(memory.content)                episodicRepo.storeEmbeddingForMemory(                    memoryId = storeResult.data.value,                    vector = embedding,                )            } catch (t: Throwable) {                Timber.tag("NOUS.Memory").w(t, "Embedding computation failed — memory stored without vector.")                // Non-fatal: memory is still searchable via keyword FTS4.            }        }        return storeResult    }    /**     * Get all known user facts.     */    override suspend fun getUserFacts(): Result<List<UserFact>> {        return userFactRepo.getAll()    }    /**     * Get active KG entities mentioned in the current session.     * Used for coreference resolution ("call mom" → who is "mom"?).     */    override suspend fun getActiveEntities(sessionId: SessionId): Result<List<KgEntity>> {        return try {            // Get all KG entities (simplified — production would filter by session)            val allEntities = kgRepo.getEntitiesByType("PERSON")            when (allEntities) {                is Result.Success -> {                    val kgEntities = allEntities.data.map { entity ->                        kgRepo.toKgEntity(entity, mentionedInSession = false)                    }                    Result.Success(kgEntities, CorrelationId.generate(), 0)                }                else -> Result.Success(emptyList(), CorrelationId.generate(), 0)            }        } catch (e: Exception) {            Timber.e(e, "getActiveEntities failed")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    /**     * Forget a memory (user-initiated — soft delete/tombstone).     */    override suspend fun forget(memoryId: MemoryId): Result<Unit> {        return episodicRepo.forget(memoryId)    }    /**     * Forget all memories (factory reset within app).     */    override suspend fun forgetAll(): Result<Unit> {        return episodicRepo.forgetAll()    }}